const order = $('Webhook').item.json.body || {};

if (!order.id && !order.number) {
  return [];
}

const num = order.number || order.id || 'unknown';
const total = `${order.currency || 'PHP'} ${order.total || '0.00'}`;
const status = order.status || 'unknown';

const b = order.billing || {};
const name = `${b.first_name || ''} ${b.last_name || ''}`.trim() || 'No name';
const phone = b.phone || 'No phone';
const email = b.email || 'No email';

const s = order.shipping && order.shipping.address_1 ? order.shipping : b;
const addressParts = [
  s.address_1,
  s.address_2,
  s.city,
  s.postcode
].filter(p => p && String(p).trim() !== '');
const address = addressParts.join(', ') || 'No address';

const items = (order.line_items || [])
  .map(i => `• ${i.quantity} x ${i.name}`)
  .join('\n') || '• (no items listed)';

const note = order.customer_note ? `\n\nNote: ${order.customer_note}` : '';

const text = [
  `🛎️ NEW ORDER #${num}`,
  ``,
  `${name}`,
  `${phone}`,
  `${email}`,
  ``,
  items,
  ``,
  `Total: ${total}`,
  `Status: ${status}`,
  ``,
  `Deliver to:`,
  address
].join('\n') + note;

return [{ json: { text } }];
